select
,app.FLOW_STATUS flowStatus,app.BACK_COL1 curEmpNames

    ,(select t2.MSG_STATUS from flow_message_dispose t2 where t2.del_flag = '0' and t2.mid = t.id and t2.BUSS_ID = #{userId}) msgStatus


from flow_message_info t
left join FLOW_APPLY_INFO app on app.del_flag = '0' and app.BILL_OID = t.BILL_OID
where t.del_flag = '0'
     and t.id = #{id}
     and t.message_no = #{messageNo}
     and t.BILL_OID = #{billOid}
     and t.BUSS_TYPE = #{bussType}
     and t.FLOW_RUID = #{flowRuid}
     and t.MSG_TITLE like concat('%', #{msgTitle}, '%')
     and t.MSG_CONTEXT like concat('%', #{msgContext}, '%')
     and t.MSG_TYPE = #{msgType}
     and t.MSG_URL = #{msgUrl}
     and t.PC_OID = #{pcOid}
     and t.APPLY_NAME like concat('%', #{applyName}, '%')
     and t.BACK_COL1 = #{backCol1}
     and t.BACK_COL2 = #{backCol2}
     and t.BACK_COL3 = #{backCol3}
     and t.sort = #{sort}
     and t.eps_id = #{epsId}
     and t.create_by = #{createBy}



       and t.MSG_TYPE = '2'
       and  exists (select 1 from flow_message_dispose t1 where t1.del_flag = '0' and t1.mid = t.id and t1.BUSS_ID = #{userId} and t1.MSG_STATUS = '2')




       and t.MSG_TYPE = '2'
       and  exists (select 1 from flow_message_dispose t1 where t1.del_flag = '0' and t1.mid = t.id and t1.BUSS_ID = #{userId} and t1.MSG_STATUS = '1')




       and t.MSG_TYPE = '2'
       and  exists (select 1 from flow_message_dispose t1 where t1.del_flag = '0' and t1.mid = t.id and t1.BUSS_ID = #{userId} and t1.MSG_STATUS = '1')
       and app.FLOW_STATUS = '3'




      and t.MSG_TYPE = '1'
      and  exists (select 1 from flow_message_dispose t1 where t1.del_flag = '0' and t1.mid = t.id and t1.BUSS_ID = #{userId})


  order by t.create_time desc,t.id

select

from flow_message_info t
where t.ID = #{id}

