update flow_message_info
BILL_OID = #{billOid}, message_no = #{messageNo}, BUSS_TYPE = #{bussType}, FLOW_RUID = #{flowRuid}, MSG_TITLE = #{msgTitle}, MSG_CONTEXT = #{msgContext}, MSG_TYPE = #{msgType}, MSG_URL = #{msgUrl}, PC_OID = #{pcOid}, APPLY_NAME = #{applyName}, BACK_COL1 = #{backCol1}, BACK_COL2 = #{backCol2}, BACK_COL3 = #{backCol3}, sort = #{sort}, eps_id = #{epsId}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime},
